{
  "answer": "PEP 8 asks to limit all lines to a maximum of 79 characters. For flowing long blocks of text such as docstrings or comments, the limit should be 72 characters.",
  "citations": [
    {
      "chunk": 3,
      "quote": "Limit all lines to a maximum of 79 characters."
    },
    {
      "chunk": 3,
      "quote": "For flowing long blocks of text with fewer structural restrictions\n(docstrings or comments), the line length should be limited to 72\ncharacters."
    }
  ]
}
